function startDeathReplay() { if (deathReplayTimer) clearInterval(deathReplayTimer); const caption=$('replayCaption'); const room=$('deathReplay'); const scenes=state.killScenes.length ? state.killScenes.slice(-4) : ['THE DARK CLOSES IN']; let index=0; room.classList.remove('replay-live'); void room.offsetWidth; room.classList.add('replay-live'); caption.textContent=`FLASHBACK // ${scenes[index]}`; deathReplayTimer=window.setInterval(() => { index=(index+1)%scenes.length; caption.textContent=`FLASHBACK // ${scenes[index]}`; room.classList.remove('replay-live'); void room.offsetWidth; room.classList.add('replay-live'); },2200); }
function showDeathMemorial() { $('deadName').textContent=state.heroName; $('deadYears').textContent=`${state.birthYear} — ${state.birthYear + 24 + Math.floor(Math.random()*34)}`; $('deathStats').textContent=`KILLS // ${state.killCount} · DEEPEST FLOOR // ${String(state.floor + 1).padStart(2,'0')}`; $('deathScenes').innerHTML=state.killScenes.length ? state.killScenes.slice(-4).reverse().map(scene => `<p>${scene}</p>`).join('') : '<p>The final moments were lost to the dark.</p>'; $('deadFamily').textContent=`A note was sent to ${state.heroName}'s family.`; $('deadQuote').textContent=deathQuotes[Math.floor(Math.random()*deathQuotes.length)]; $('deathModal').classList.remove('hidden'); startDeathReplay(); }
function returnToCamp() { if (deathReplayTimer) clearInterval(deathReplayTimer); deathReplayTimer=null; $('deathModal').classList.add('hidden'); render(); log('The camp remembers you. A new run can begin.'); }
function defeatRun() { stopCombatLoop(); state.backpack=[]; state.equipped={weapon:null,armor:null,helmet:null,charm:null}; state.floor=0; state.relics=0; state.currentLoot=null; state.phase='combat'; state.started=false; state.maxHp=100; state.hp=100; recalculateStats(); $('stairsModal').classList.add('hidden'); $('shopModal').classList.add('hidden'); $('packModal').classList.add('hidden'); $('startCopy').textContent='You died in the dark. Your dungeon loot is gone. The coins remain.'; $('startOverlay').classList.add('is-hidden'); $('runMessage').textContent='THE DUNGEON TAKES EVERYTHING. RETURN TO CAMP.'; render(); log('You wake at camp. The lost loot is gone, but the ground is safe.'); showDeathMemorial(); }

function rollLoot() { const pool=enemies[state.floor].loot; return itemCopy(pool[Math.floor(Math.random()*pool.length)]); }
function openChest(chestId) { if (!state.started || state.phase !== 'combat') return; const key=`${state.floor}-${chestId}`; if (state.openedChests[key]) { log('This chest is already empty.'); return; } state.openedChests[key]=true; questProgress('chest'); playTone(520,.16,'triangle',.04); const coinDrop=6 + state.floor * 4 + Math.floor(Math.random()*8); state.coins += coinDrop; const item=rollLoot(); const stored=state.backpack.length < state.backpackCapacity; if (stored) state.backpack.push(item); log(`Chest opened. +${coinDrop} coins${stored ? ` and ${item.name} added to your pack.` : ', but your pack is full.'}`); const chest=document.querySelector(`[data-chest="${chestId}"]`); if (chest) chest.classList.add('opened'); render(); }
function winRoom() { stopCombatLoop(); if (state.tutorialActive) { const tutorialWeapon=itemCopy({name:'CAMPBLADE',rarity:'common',type:'weapon',icon:'†',desc:'Your first real weapon.',stats:{attack:5}}); state.equipped.weapon=tutorialWeapon; state.tutorialActive=false; state.tutorialSeen=true; state.relics+=1; recalculateStats(); state.phase='combat'; $('sceneMessage').textContent='TUTORIAL CLEAR'; $('runMessage').textContent='FIRST WEAPON EQUIPPED.'; log('Training complete. CAMPBLADE equipped. The dungeon starts now.'); render(); resetEnemy(); return; } questProgress('defeat'); state.phase='loot'; state.currentLoot=rollLoot(); const coinDrop=12 + state.floor * 8 + (enemies[state.floor].boss ? 45 : 0); state.coins += coinDrop; $('sceneMessage').textContent=enemies[state.floor].boss ? 'BOSS REWARD' : 'ROOM CLEAR'; $('runMessage').textContent='CHOOSE: EQUIP IT OR PACK IT.'; log(`${enemies[state.floor].name} falls. +${coinDrop} coins. Choose your drop.`); render(); }
function recordKill() { const enemy=state.tutorialActive ? tutorialEnemy : enemies[state.floor]; state.killCount+=1; state.killScenes.push(`DEFEATED ${enemy.name} // FLOOR ${state.tutorialActive ? 'CAMP' : state.floor + 1}`); }
const originalWinRoom=winRoom;
winRoom=function() { recordKill(); originalWinRoom(); };
function finishLoot(action) { if (state.phase !== 'loot' || !state.currentLoot) return; if (action === 'stash') { if (state.backpack.length >= state.backpackCapacity) { log('Backpack full. Equip it or make space first.'); return; } state.backpack.push(state.currentLoot); log(`${state.currentLoot.name} stored. ${state.backpackCapacity - state.backpack.length} slots remain.`); } if (action === 'equip') { const slot=state.currentLoot.type; const old=state.equipped[slot]; if (old && state.backpack.length >= state.backpackCapacity) { log('Backpack full. Sell something before swapping gear.'); return; } if (old) state.backpack.push(old); state.equipped[slot]=state.currentLoot; recalculateStats(); log(`${state.currentLoot.name} equipped. Your stats changed.`); } state.relics+=1; state.currentLoot=null; state.phase='descend'; $('runMessage').textContent='A NEW FLOOR IS WAITING.'; $('sceneMessage').textContent='DESCEND'; render(); }
