function setGuard(value,event) { if (event) event.preventDefault(); if (state.phase !== 'combat') return; state.guarding=value; $('sceneMessage').textContent=value ? 'GUARDING' : 'HOLD TO CHARGE'; render(); }
function movePlayer(dx,dy) { if (state.phase === 'loot' || state.phase === 'safe') return; const stride=.28; state.position.x=Math.max(1,Math.min(9,state.position.x + dx * stride)); state.position.y=Math.max(1,Math.min(6,state.position.y + dy * stride)); renderWorld(); if (!state.started) { if (state.position.x >= 4 && state.position.x <= 6 && state.position.y >= 5) { openDungeonEntry(); } else { updateServicePrompt(); } return; } if (state.position.x >= 8 && state.position.y >= 5) { if (state.phase === 'descend') descend(); else log('The stairwell is sealed. Clear the room first.'); } else if (state.position.x >= 6 && state.position.y >= 5) { log('A battered chest waits in the corner.'); } else { log('You move across the dungeon floor.'); } }

function renderLootCard() { const item=state.currentLoot; $('lootIcon').textContent=item.icon; $('lootRarity').textContent=`${rarityLabels[item.rarity]} // ${item.type.toUpperCase()}`; $('lootRarity').className=`eyebrow rarity-${item.rarity.replace('?', 'unknown')}`; $('lootName').textContent=item.name; $('lootDescription').textContent=`${itemStatText(item)} · ${item.desc}`; $('stashButton').disabled=state.backpack.length >= state.backpackCapacity; }
function renderIndex() { $('indexGrid').innerHTML=enemies.map((enemy,index) => `<article class="index-card ${enemy.boss ? 'boss-card' : ''}"><div class="index-card-top"><span class="index-floor">0${index+1}</span><span class="index-depth">${enemy.depth}m</span></div><div class="index-monster-glyph">${enemy.boss ? '♛' : index === 0 ? '◒' : index === 1 ? '◈' : '⬟'}</div><h3>${enemy.name}</h3><p>${enemy.room}${enemy.boss ? ' · BOSS' : ''}</p><div class="index-loot">${enemy.loot.map(item => `<span class="loot-line"><b class="rarity-${item.rarity.replace('?', 'unknown')}">${rarityLabels[item.rarity]}</b>${item.name}<small>${itemStatText(item)}</small></span>`).join('')}</div></article>`).join(''); }
function renderPack() { $('statStrip').innerHTML=`<span>ATK <b>${state.stats.attack}</b></span><span>DEF <b>${state.stats.defense}</b></span><span>HP <b>${state.stats.health}</b></span><span>STA <b>${state.stats.stamina}</b></span>`; $('equipmentGrid').innerHTML=Object.entries(state.equipped).map(([slot,item]) => `<div class="equip-slot"><span>${slot.toUpperCase()}</span><strong>${item ? item.name : 'EMPTY'}</strong><small>${item ? itemStatText(item) : 'No gear equipped'}</small>${item ? `<button class="mini-button gear-store" data-store-equipped="${slot}" type="button">STORE</button>` : ''}</div>`).join(''); $('packList').innerHTML=state.backpack.length ? state.backpack.map(item => `<div class="pack-item"><span class="pack-icon">${item.icon}</span><div><b class="rarity-${item.rarity.replace('?', 'unknown')}">${rarityLabels[item.rarity]}</b><strong>${item.name}</strong><small>${itemStatText(item)}</small></div><button class="mini-button pack-equip" data-uid="${item.uid}" type="button">EQUIP</button><button class="mini-button gear-store" data-store-pack="${item.uid}" type="button">STORE</button></div>`).join('') : '<p class="empty-pack">Your backpack is empty. Keep moving.</p>'; renderStorage(); }
function renderStorage() { const label=$('storageCount'); if (label) label.textContent=`${state.storage.length}/${state.storageCapacity}`; const list=$('storageList'); if (!list) return; list.innerHTML=state.storage.length ? state.storage.map(item => `<div class="pack-item storage-item"><span class="pack-icon">${item.icon}</span><div><b class="rarity-${item.rarity.replace('?', 'unknown')}">${rarityLabels[item.rarity]}</b><strong>${item.name}</strong><small>${itemStatText(item)}</small></div><button class="mini-button storage-take" data-storage-uid="${item.uid}" type="button">TAKE</button></div>`).join('') : '<p class="empty-pack">The storage chest is empty.</p>'; }
function sellPrice(item) { return Math.max(5, Math.floor((rarityPrices[item.rarity] || 18) * .45)); }
function renderPackWithSell() { renderPack(); document.querySelectorAll('#packList .pack-item').forEach((row,index) => { const button=document.createElement('button'); button.className='mini-button sell-button'; button.dataset.sell=state.backpack[index].uid; button.type='button'; button.textContent=`SELL ${sellPrice(state.backpack[index])}`; row.appendChild(button); }); }
function sellFromPack(uid) { const index=state.backpack.findIndex(item => item.uid === uid); if (index < 0) return; const item=state.backpack[index]; state.backpack.splice(index,1); state.coins += sellPrice(item); renderPackWithSell(); render(); log(`${item.name} sold for ${sellPrice(item)} coins.`); }
function allShopTemplates() { return enemies.flatMap(enemy => enemy.loot); }
function refreshShop(force=false) { if (force && state.coins < 5) { log('The shop refresh costs 5 coins.'); return; } if (force) state.coins -= 5; const pool=allShopTemplates(); const used=new Set(); state.shopStock=[]; while (state.shopStock.length < 3) { const template=pool[Math.floor(Math.random()*pool.length)]; if (used.has(template.name)) continue; used.add(template.name); const item=itemCopy(template); item.price=rarityPrices[item.rarity] + Math.floor(Math.random()*12); state.shopStock.push(item); } renderShop(); render(); }
function renderShop() { $('shopCoinValue').textContent=String(state.coins).padStart(2,'0'); const level=Math.floor((state.backpackCapacity - 10) / 5); const upgradePrice=packUpgradePrices[level]; const upgradeButton=$('upgradePackButton'); upgradeButton.textContent=upgradePrice ? `PACK +5 · ${upgradePrice}` : 'PACK MAX'; upgradeButton.disabled=!upgradePrice || state.coins < upgradePrice; $('shopGrid').innerHTML=''; state.shopStock.forEach(item => { const card=document.createElement('article'); card.className='shop-card'; card.innerHTML=`<div class="shop-icon">${item.icon}</div><b class="rarity-${item.rarity.replace('?', 'unknown')}">${rarityLabels[item.rarity]}</b><h3>${item.name}</h3><p>${itemStatText(item)}<br>${item.desc}</p>`; const button=document.createElement('button'); button.className='mini-button shop-buy'; button.dataset.buy=item.uid; button.type='button'; button.textContent=`BUY · ${item.price}`; card.appendChild(button); $('shopGrid').appendChild(card); }); }
function upgradeBackpack() { const level=Math.floor((state.backpackCapacity - 10) / 5); const price=packUpgradePrices[level]; if (!price) { log('Your backpack is fully upgraded.'); return; } if (state.coins < price) { log(`You need ${price - state.coins} more coins for the next pack shape.`); return; } state.coins -= price; state.backpackCapacity += 5; renderShop(); render(); $('playerVisual').classList.add('pack-upgrade-flash'); window.setTimeout(() => $('playerVisual').classList.remove('pack-upgrade-flash'),700); log(`Backpack upgraded. It now holds ${state.backpackCapacity} items.`); }
function openShop() { if (!state.shopStock.length) refreshShop(false); renderShop(); $('shopModal').classList.remove('hidden'); }
let surfaceInteraction={service:null,charge:0,timer:null};
function nearbySurfaceService() { if (state.started) return null; const {x,y}=state.position; if (x <= 3 && y >= 3 && y <= 5) return {id:'shop',title:'EQUIPMENT SHOP'}; if (x >= 7 && y <= 4) return {id:'class',title:'CLASS HALL'}; if (x >= 6 && y >= 3 && y <= 4) return {id:'crew',title:'RECRUIT HALL'}; if (x >= 7 && y >= 5) return {id:'pack',title:'PACK UPGRADE'}; return null; }
function updateServicePrompt() { const service=nearbySurfaceService(); surfaceInteraction.service=service; if (!service) { $('servicePrompt').classList.add('hidden'); return; } $('servicePromptTitle').textContent=service.title; $('servicePrompt').classList.remove('hidden'); }
function openSurfaceService(service=surfaceInteraction.service) { if (!service) return false; if (service.id === 'shop' || service.id === 'pack') openShop(); if (service.id === 'class') { renderClassPicker(); $('classModal').classList.remove('hidden'); } if (service.id === 'crew') { renderCrewList(); $('crewModal').classList.remove('hidden'); } log(`${service.title} opens.`); $('servicePrompt').classList.add('hidden'); return true; }
function beginServiceEntry(event) { if (event) event.preventDefault(); if (!surfaceInteraction.service || surfaceInteraction.timer) return; surfaceInteraction.charge=0; $('servicePrompt').classList.remove('hidden'); surfaceInteraction.timer=window.setInterval(() => { surfaceInteraction.charge=Math.min(1,surfaceInteraction.charge+.08); $('serviceCharge').style.width=`${surfaceInteraction.charge * 100}%`; if (surfaceInteraction.charge >= 1) { finishServiceEntry(); } },45); }
function finishServiceEntry() { if (surfaceInteraction.timer) { clearInterval(surfaceInteraction.timer); surfaceInteraction.timer=null; } if (surfaceInteraction.charge >= 1) openSurfaceService(); else { surfaceInteraction.charge=0; $('serviceCharge').style.width='0%'; } }
function buyShopItem(uid) { const index=state.shopStock.findIndex(item => item.uid === uid); if (index < 0) return; const item=state.shopStock[index]; if (state.coins < item.price) { log(`You need ${item.price - state.coins} more coins.`); return; } if (state.backpack.length >= state.backpackCapacity) { log('Backpack full. Sell something before shopping.'); return; } state.coins -= item.price; state.backpack.push(item); state.shopStock.splice(index,1); renderShop(); render(); log(`${item.name} bought. Pack it or equip it before the next descent.`); }
function renderCrewList() { if (!$('crewList')) return; $('crewList').innerHTML=state.companions.length ? state.companions.map(companion => `<article class="crew-card ${companion.alive ? '' : 'fallen'}"><div class="crew-avatar armor-${companion.armor} companion-${companion.gender}"><span></span></div><div><b>${companion.name}</b><strong>${companion.role.toUpperCase()}</strong><small>${companion.gender} · ${companion.armor} armor · ${companion.weapon}</small></div><em>${companion.alive ? `${Math.ceil(companion.hp)}/${companion.maxHp} HP` : 'FALLEN'}</em></article>`).join('') : '<p class="empty-pack">No companions hired yet. The dungeon is louder alone.</p>'; const active=state.companions.filter(companion => companion.alive).length; $('hireCrewButton').disabled=active >= 2; $('hireCrewButton').textContent=active >= 2 ? 'CREW FULL' : `HIRE RANDOM · ${35 + active * 15}`; }
function hireCompanion() { const active=state.companions.filter(companion => companion.alive).length; if (active >= 2) { log('Your crew is full. Two companions can follow you.'); return; } const cost=35 + active * 15; if (state.coins < cost) { log(`You need ${cost - state.coins} more coins to hire help.`); return; } const look=companionLooks[Math.floor(Math.random()*companionLooks.length)]; const available=companionNames.filter(name => !state.companions.some(companion => companion.name === name)); const name=available[Math.floor(Math.random()*available.length)]; state.coins -= cost; state.companions.push({name,...look,hp:30 + active * 10,maxHp:30 + active * 10,alive:true}); questProgress('crew'); renderCrewList(); render(); log(`${name} joined your crew. ${look.role} ready.`); }
function equipFromPack(uid) { const index=state.backpack.findIndex(item => item.uid === uid); if (index < 0) return; const item=state.backpack[index]; const old=state.equipped[item.type]; state.backpack.splice(index,1); if (old) state.backpack.push(old); state.equipped[item.type]=item; recalculateStats(); render(); log(`${item.name} equipped from your backpack.`); }
function storeItem(item, source, slot='') { if (!item || state.storage.length >= state.storageCapacity) { log('Storage is full. Take something out first.'); return; } if (source === 'pack') { const index=state.backpack.findIndex(entry => entry.uid === item.uid); if (index < 0) return; state.backpack.splice(index,1); } else { state.equipped[slot]=null; recalculateStats(); } state.storage.push(item); renderPackWithSell(); render(); log(`${item.name} placed safely in the storage chest.`); }
function storeFromPack(uid) { storeItem(state.backpack.find(item => item.uid === uid),'pack'); }
function storeEquipped(slot) { storeItem(state.equipped[slot],'equipped',slot); }
function takeFromStorage(uid) { const index=state.storage.findIndex(item => item.uid === uid); if (index < 0) return; if (state.backpack.length >= state.backpackCapacity) { log('Backpack full. Upgrade it or equip an item first.'); return; } const item=state.storage.splice(index,1)[0]; state.backpack.push(item); renderPackWithSell(); render(); log(`${item.name} taken from storage and added to your backpack.`); }
function chooseClass(id) { const item=classData[id]; if (!item) return; if (!state.unlockedClasses[id]) { if (state.coins < item.cost) { $('selectedClassLabel').textContent=`NEED ${item.cost - state.coins} MORE COINS`; return; } state.coins -= item.cost; state.unlockedClasses[id]=true; log(`${item.name} class unlocked.`); } state.classId=id; recalculateStats(); render(); }
function chooseControlMode(mode) { state.controlMode=mode; document.querySelectorAll('[data-control-mode]').forEach(button => button.classList.toggle('selected',button.dataset.controlMode === mode)); document.querySelector('.game-frame').classList.toggle('computer-mode',mode === 'computer'); document.querySelector('.game-frame').classList.toggle('mobile-mode',mode === 'mobile'); log(mode === 'computer' ? 'Computer controls selected. Hold SPACE to charge, then release.' : 'Mobile controls selected. Hold STRIKE to charge, then release.'); }

$('startButton').addEventListener('click',startRun); $('attackButton').addEventListener('pointerdown',beginCharge); $('attackButton').addEventListener('pointerup',releaseCharge); $('attackButton').addEventListener('pointercancel',releaseCharge); $('attackButton').addEventListener('pointerleave',event => { if (state.charging) releaseCharge(event); }); $('guardButton').addEventListener('pointerdown',event => setGuard(true,event)); $('guardButton').addEventListener('pointerup',event => setGuard(false,event)); $('guardButton').addEventListener('pointercancel',event => setGuard(false,event)); $('guardButton').addEventListener('pointerleave',event => { if (state.guarding) setGuard(false,event); }); $('shiftButton').addEventListener('click',() => { if (state.phase !== 'combat') return; state.shifted=!state.shifted; log(state.shifted ? 'You slip to the side. The next hit may miss.' : 'You settle back into the center.'); render(); });
$('equipButton').addEventListener('click',() => finishLoot('equip')); $('stashButton').addEventListener('click',() => finishLoot('stash')); $('descendButton').addEventListener('click',descend); $('continueButton').addEventListener('click',continueDown); $('retreatButton').addEventListener('click',retreatRun); $('backpackButton').addEventListener('click',() => { renderPackWithSell(); $('packModal').classList.remove('hidden'); }); $('storageBox').addEventListener('click',() => { renderPackWithSell(); $('packModal').classList.remove('hidden'); }); $('classButton').addEventListener('click',() => { renderClassPicker(); $('classModal').classList.remove('hidden'); }); $('shopButton').addEventListener('click',openShop); $('startShopButton').addEventListener('click',openShop); $('crewButton').addEventListener('click',() => { renderCrewList(); $('crewModal').classList.remove('hidden'); }); $('startCrewButton').addEventListener('click',() => { renderCrewList(); $('crewModal').classList.remove('hidden'); }); $('hireCrewButton').addEventListener('click',hireCompanion); $('refreshShopButton').addEventListener('click',() => refreshShop(true)); $('upgradePackButton').addEventListener('click',upgradeBackpack); $('indexButton').addEventListener('click',() => { renderIndex(); $('indexModal').classList.remove('hidden'); }); $('tutorialYesButton').addEventListener('click',beginTutorial); $('tutorialNoButton').addEventListener('click',skipTutorial);
$('guideButton').addEventListener('click',() => $('guideModal').classList.remove('hidden'));
$('startButton').addEventListener('click',() => { state.killCount=0; state.killScenes=[]; });
$('heroNameInput').addEventListener('input',event => { const cleaned=event.target.value.replace(/[^a-z0-9 ]/gi,'').slice(0,18); if (event.target.value !== cleaned) event.target.value=cleaned; });
$('questActionButton').addEventListener('click',acceptOrClaimQuest);
document.querySelectorAll('[data-npc]').forEach(npc => npc.addEventListener('click',() => openNpcQuest(npc.dataset.npc)));
$('returnCampButton').addEventListener('click',returnToCamp);
$('soundButton').addEventListener('click',toggleSound);
document.addEventListener('pointerdown',initAudio,{once:true});
$('buyGearButton').addEventListener('click',() => { renderShop(); log('The merchant lays out the random gear for sale.'); }); $('sellGearButton').addEventListener('click',() => { $('shopModal').classList.add('hidden'); renderPackWithSell(); $('packModal').classList.remove('hidden'); log('Choose gear from your pack to sell.'); });
$('surfaceWorld').addEventListener('click',event => { if (event.target.closest('.sign-shop')) openShop(); if (event.target.closest('.sign-class')) { renderClassPicker(); $('classModal').classList.remove('hidden'); } if (event.target.closest('.sign-crew')) { renderCrewList(); $('crewModal').classList.remove('hidden'); } if (event.target.closest('.sign-pack')) openShop(); if (event.target.closest('.sign-dungeon')) openDungeonEntry(); });
$('pixelDungeon').addEventListener('click',event => { const chest=event.target.closest('[data-chest]'); if (chest) openChest(chest.dataset.chest); });
document.querySelectorAll('[data-difficulty]').forEach(button => button.addEventListener('click',() => { state.difficulty=button.dataset.difficulty; document.querySelectorAll('[data-difficulty]').forEach(item => item.classList.toggle('selected',item === button)); })); document.querySelectorAll('[data-close]').forEach(button => button.addEventListener('click',() => $(button.dataset.close).classList.add('hidden'))); document.addEventListener('click',event => { const packButton=event.target.closest('.pack-equip'); if (packButton) equipFromPack(packButton.dataset.uid); const storePackButton=event.target.closest('[data-store-pack]'); if (storePackButton) storeFromPack(storePackButton.dataset.storePack); const storeEquippedButton=event.target.closest('[data-store-equipped]'); if (storeEquippedButton) storeEquipped(storeEquippedButton.dataset.storeEquipped); const storageButton=event.target.closest('[data-storage-uid]'); if (storageButton) takeFromStorage(storageButton.dataset.storageUid); const sellButton=event.target.closest('[data-sell]'); if (sellButton) sellFromPack(sellButton.dataset.sell); const buyButton=event.target.closest('[data-buy]'); if (buyButton) buyShopItem(buyButton.dataset.buy); const classButton=event.target.closest('[data-class]'); if (classButton) chooseClass(classButton.dataset.class); const lookButton=event.target.closest('[data-look]'); if (lookButton) { state.look=lookButton.dataset.look; document.querySelectorAll('[data-look]').forEach(item => item.classList.toggle('selected',item === lookButton)); render(); } });
let touchStartY=null; $('gameStage').addEventListener('pointerdown',event => { touchStartY=event.clientY; }); $('gameStage').addEventListener('pointerup',event => { if (touchStartY !== null && event.clientY-touchStartY > 55 && state.phase === 'descend') descend(); touchStartY=null; });
const movementTimers=new Map();
function setWalkingState(active) { const selectors=state.started ? ['#pixelPlayer','.pixel-player + .companion'] : ['#surfacePlayer','.surface-player + .companion']; selectors.forEach(selector => document.querySelectorAll(selector).forEach(entity => entity.classList.toggle('walking',active))); }
function startMoving(key,dx,dy) { if (movementTimers.has(key)) return; setWalkingState(true); movePlayer(dx,dy); movementTimers.set(key,window.setInterval(() => movePlayer(dx,dy),45)); }
function stopMoving(key) { const timer=movementTimers.get(key); if (timer) { clearInterval(timer); movementTimers.delete(key); } if (!movementTimers.size) setWalkingState(false); }
document.querySelectorAll('[data-move]').forEach(button => { const direction=button.dataset.move; const key=`touch-${direction}`; const dx=direction === 'left' ? -1 : direction === 'right' ? 1 : 0; const dy=direction === 'up' ? -1 : direction === 'down' ? 1 : 0; button.addEventListener('pointerdown',event => { event.preventDefault(); button.setPointerCapture?.(event.pointerId); startMoving(key,dx,dy); }); ['pointerup','pointercancel','pointerleave'].forEach(type => button.addEventListener(type,() => stopMoving(key))); });
document.querySelectorAll('[data-control-mode]').forEach(button => button.addEventListener('click',() => chooseControlMode(button.dataset.controlMode)));
document.addEventListener('keydown',event => { if (event.code === 'Enter') { beginServiceEntry(event); return; } if (event.code === 'Space') { event.preventDefault(); beginCharge(event); return; } const moves={ArrowUp:[0,-1],w:[0,-1],ArrowDown:[0,1],s:[0,1],ArrowLeft:[-1,0],a:[-1,0],ArrowRight:[1,0],d:[1,0]}; const move=moves[event.key]; if (move) { event.preventDefault(); startMoving(`key-${event.key}`,move[0],move[1]); } }); document.addEventListener('keyup',event => { if (event.code === 'Enter') { event.preventDefault(); finishServiceEntry(); } if (event.code === 'Space') { event.preventDefault(); releaseCharge(event); } stopMoving(`key-${event.key}`); });
renderIndex(); renderClassPicker(); $('startOverlay').classList.add('is-hidden'); document.querySelector('.game-frame').classList.add('mobile-mode'); render();
